cd /tmp/vally-eval-trial-KUefTw && cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Standard,
    Gold
}
E
cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
mkdir -p tests/CheckoutPricing.IntegrationTests/Pricing
cat > tests/CheckoutPricing.IntegrationTests/Pricing/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.IntegrationTests.Pricing;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var payable = new Checkout().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | tail -25

